<?php

namespace App\Services\Platform;

use App\Enums\InvoiceStatus;
use App\Enums\SubscriptionStatus;
use App\Models\Tenant;
use App\Models\TenantInvoice;
use App\Models\TenantSubscription;
use Carbon\CarbonImmutable;
use Illuminate\Support\Facades\DB;

/**
 * Raises the platform's bills and records them being paid.
 *
 * Everything here is safe to run twice. Invoices are generated by a scheduler that may fire
 * more than once, and settlement arrives from an M-PESA callback, which Safaricom delivers
 * repeatedly by design.
 */
class PlatformBilling
{
    public function __construct(protected BillingCalculator $calculator) {}

    /**
     * The bill that lets an ISP in at all.
     *
     * Raised on demand rather than at sign-up, so an ISP that never comes back does not leave
     * an unpaid invoice behind them.
     */
    public function onboardingInvoice(Tenant $tenant): TenantInvoice
    {
        $subscription = TenantSubscription::forTenant($tenant);

        $existing = TenantInvoice::query()
            ->where('tenant_id', $tenant->id)
            ->where('kind', TenantInvoice::KIND_ONBOARDING)
            ->first();

        if ($existing !== null) {
            return $existing;
        }

        return TenantInvoice::query()->create([
            'tenant_id' => $tenant->id,
            'kind' => TenantInvoice::KIND_ONBOARDING,
            'onboarding_amount' => $subscription->onboarding_fee,
            'total' => $subscription->onboarding_fee,
            'breakdown' => ['onboarding' => ['amount' => (float) $subscription->onboarding_fee]],
            // Due immediately: nothing else can happen until it is paid.
            'due_at' => now(),
        ]);
    }

    /**
     * Bill one ISP for a month that has ended.
     *
     * Returns null when there is nothing to charge — a month with no HotSpot sales and no
     * PPPoE lines is a month the ISP owes nothing for, and an invoice for zero is a bill that
     * can go overdue and cost them the console for owing nothing.
     */
    public function invoiceForPeriod(Tenant $tenant, ?CarbonImmutable $start = null): ?TenantInvoice
    {
        $start ??= CarbonImmutable::now()->subMonthNoOverflow()->startOfMonth();
        $end = $start->endOfMonth();

        $existing = TenantInvoice::query()
            ->where('tenant_id', $tenant->id)
            ->where('kind', TenantInvoice::KIND_USAGE)
            ->whereDate('period_start', $start->toDateString())
            ->first();

        if ($existing !== null) {
            return $existing;
        }

        $charge = $this->calculator->forTenant($tenant, $start, $end);

        if ($charge->isZero()) {
            return null;
        }

        $invoice = TenantInvoice::query()->create([
            'tenant_id' => $tenant->id,
            'kind' => TenantInvoice::KIND_USAGE,
            'period_start' => $start->toDateString(),
            'period_end' => $end->toDateString(),
            'hotspot_amount' => $charge->hotspotAmount,
            'pppoe_amount' => $charge->pppoeAmount,
            'total' => $charge->total(),
            'breakdown' => $charge->breakdown(),
            'due_at' => now()->addDays((int) config('platform.terms.due_after_days')),
        ]);

        $subscription = TenantSubscription::forTenant($tenant);
        $subscription->last_invoiced_on = $end;
        $subscription->save();

        return $invoice;
    }

    /**
     * Record an invoice as settled and put the ISP back on their feet.
     *
     * Re-reads the row first: a callback and a poll can land together, and an invoice paid
     * twice would show the ISP a credit they do not have.
     */
    public function markPaid(TenantInvoice $invoice): TenantInvoice
    {
        $invoice->refresh();

        if ($invoice->status === InvoiceStatus::Paid) {
            return $invoice;
        }

        DB::transaction(function () use ($invoice): void {
            $invoice->status = InvoiceStatus::Paid;
            $invoice->paid_at = now();
            $invoice->save();

            $tenant = $invoice->tenant;

            if ($tenant === null) {
                return;
            }

            $subscription = TenantSubscription::forTenant($tenant);

            if ($invoice->kind === TenantInvoice::KIND_ONBOARDING) {
                $subscription->onboarding_paid_at ??= now();
                $subscription->period_started_on ??= CarbonImmutable::now();
            }

            // Paying restores access at once. An ISP who has just settled their bill and is
            // still locked out will assume the payment failed and pay again.
            if ($subscription->status !== SubscriptionStatus::Cancelled) {
                $subscription->status = $subscription->onboardingIsPaid() && ! $subscription->hasLapsedInvoice()
                    ? SubscriptionStatus::Active
                    : SubscriptionStatus::Pending;
            }

            $subscription->save();
        });

        return $invoice->refresh();
    }

    /**
     * Move bills past their due date to overdue, and suspend the ISPs whose grace has run out.
     *
     * Only ever tightens on the strength of a date. Restoring access is settlement's job.
     *
     * @return array{overdue: int, suspended: int}
     */
    public function sweepOverdue(): array
    {
        $overdue = TenantInvoice::query()
            ->where('status', InvoiceStatus::Pending)
            ->whereNotNull('due_at')
            ->where('due_at', '<', now())
            ->update(['status' => InvoiceStatus::Overdue]);

        $suspended = 0;
        $grace = (int) config('platform.terms.grace_days');

        $lapsed = TenantInvoice::query()
            ->outstanding()
            ->whereNotNull('due_at')
            ->where('due_at', '<=', now()->subDays($grace))
            ->pluck('tenant_id')
            ->unique();

        foreach ($lapsed as $tenantId) {
            $subscription = TenantSubscription::query()->where('tenant_id', $tenantId)->first();

            if ($subscription === null || $subscription->status !== SubscriptionStatus::Active) {
                continue;
            }

            $subscription->status = SubscriptionStatus::Suspended;
            $subscription->save();
            $suspended++;
        }

        return ['overdue' => (int) $overdue, 'suspended' => $suspended];
    }
}
